#!/bin/sh
# aapcslane.sh -- the RUNNING AAPCS64 (Apple) ABI lane: tiko-compiled code against a
# clang-built C library on the Mac, called and calling back.
#
#   build/aapcslane.sh              the Mac (macos-arm64), then the linux-x86_64 control in WSL
#   build/aapcslane.sh --mac-only   the Mac alone
#
# tests/abi/apple/lane.c and lane.tiko (GENERATED by build/aapcslane.py from one table):
# every shape -- integer aggregates of 1 to 33 bytes, HFAs of 1 to 5 floats and doubles
# (nested, arrayed, a union), mixed and non-HFA unions, over-16-byte ones by address -- passed
# and returned by value in both directions, through procedure pointers both ways,
# register-exhausting prefixes, and varargs both ways. C owns main and makes every check, so
# the tiko side needs no runtime: it links nothing of tiko-rt.
#
# WHY: build/aapcsig.sh proves tiko's IR SIGNATURES equal clang's, which decides the
# registers -- but only a real caller and callee prove the bytes arrive (docs/tiko-macos M3).
# The linux-x86_64 run of the same lane is the control: it passes, so a Mac failure is the
# Apple ABI, not the lane.
#
# Needs: bin/tiko built; ssh to the Mac (TIKO_MAC_HOST, default 'mac'; extra ssh options in
# TIKO_MAC_SSH_OPTS) with the Command Line Tools and Homebrew LLVM there; WSL with clang for
# the control. Exits 1 on any failure.

ROOT=$(cd "$(dirname "$0")/.." && pwd)
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*) EXT=".exe" ;;
    *) echo "aapcslane: run from Windows (it drives ssh and WSL)" >&2; exit 3 ;;
esac
TKO="$ROOT/bin/tiko$EXT"
[ -x "$TKO" ] || { echo "aapcslane: build tiko first (build/build.sh)" >&2; exit 3; }
HOST=${TIKO_MAC_HOST:-mac}
SSHO=${TIKO_MAC_SSH_OPTS:-}
MACONLY=0
[ "${1:-}" = "--mac-only" ] && MACONLY=1
PY=${PYTHON:-python}
command -v "$PY" > /dev/null 2>&1 || PY=python3

"$PY" -I "$ROOT/build/aapcslane.py" --check || exit 2

W="$ROOT/build/.aapcslane"
mkdir -p "$W"
fail=0

# ------------------------------------------------------------------ the Mac
"$TKO" -c -target macos-arm64 "$ROOT/tests/abi/apple/lane.tiko" -o "$W/lane-mac.o" > "$W/tiko-mac.log" 2>&1 \
    || { echo "FAIL mac: tiko did not compile lane.tiko"; head -5 "$W/tiko-mac.log"; exit 1; }
cp "$ROOT/tests/abi/apple/lane.c" "$W/lane.c"
# THE REMOTE STEP IS A FILE, run by a login zsh: a non-login ssh shell has no Homebrew on
# PATH, and variables in an inline ssh command expand on the wrong side.
cat > "$W/mac.sh" <<'EOF'
set -u
cd ~/tkm/aapcslane || exit 2
CC=/opt/homebrew/opt/llvm/bin/clang
[ -x $CC ] || CC=/usr/bin/clang
SDK=$(xcrun --show-sdk-path)
$CC -target arm64-apple-macosx13.0 -isysroot $SDK -O1 -c lane.c -o lane-c.o || { print "rc=2 clang lane.c"; exit 2; }
$CC -target arm64-apple-macosx13.0 -isysroot $SDK lane-c.o lane-mac.o -o lane || { print "rc=2 link"; exit 2; }
./lane
print "rc=$?"
EOF
sed -i 's/\r$//' "$W/mac.sh"
# shellcheck disable=SC2086
ssh -o BatchMode=yes $SSHO "$HOST" 'mkdir -p ~/tkm/aapcslane' < /dev/null || { echo "FAIL mac: no ssh to $HOST"; exit 3; }
# shellcheck disable=SC2086
scp -q -o BatchMode=yes $SSHO "$W/lane.c" "$W/lane-mac.o" "$W/mac.sh" "$HOST:tkm/aapcslane/" || { echo "FAIL mac: scp"; exit 3; }
# shellcheck disable=SC2086
ssh -o BatchMode=yes $SSHO "$HOST" zsh -l tkm/aapcslane/mac.sh < /dev/null > "$W/mac.out" 2>&1
cat "$W/mac.out"
grep -q '^rc=0$' "$W/mac.out" || { echo "FAIL mac-arm64 lane"; fail=1; }

# ------------------------------------------------------------------ the control
if [ "$MACONLY" = "0" ]; then
    "$TKO" -c -target linux-x86_64 "$ROOT/tests/abi/apple/lane.tiko" -o "$W/lane-linux.o" > "$W/tiko-linux.log" 2>&1 \
        || { echo "FAIL linux: tiko did not compile lane.tiko"; head -5 "$W/tiko-linux.log"; exit 1; }
    mnt( ) { echo "$1" | sed 's#^/\([a-zA-Z]\)/#/mnt/\L\1/#'; }
    cat > "$W/linux.sh" <<EOF
set -u
D=\$HOME/aapcslane; mkdir -p \$D; cd \$D
cp "$(mnt "$W")/lane.c" "$(mnt "$W")/lane-linux.o" .
clang -O1 -c lane.c -o lane-c.o || { echo "rc=2 clang"; exit 2; }
clang lane-c.o lane-linux.o -o lane || { echo "rc=2 link"; exit 2; }
./lane
echo "rc=\$?"
EOF
    sed -i 's/\r$//' "$W/linux.sh"
    MSYS_NO_PATHCONV=1 wsl.exe -- bash "$(mnt "$W")/linux.sh" < /dev/null > "$W/linux.out" 2>&1
    sed 's/^/linux-x86_64 control: /' "$W/linux.out"
    grep -q '^rc=0$' "$W/linux.out" || { echo "FAIL linux-x86_64 control"; fail=1; }
fi

[ "$fail" = "0" ] && echo "aapcslane: ok"
exit $fail
